func (p *OrderProc) Apply(ctx context.Context, ev Event) error {
    switch p.State {
    case AwaitingPayment:
        if ev.Kind != PaymentOK {
            return nil                       // stale or duplicate reply
        }
        p.State = AwaitingStock
        return p.outbox.Enqueue(ctx, ReserveStock{CID: p.CorrelationID})
    case AwaitingStock:
        p.State = Done
        return p.outbox.Enqueue(ctx, Ship{CID: p.CorrelationID})
    default:
        return fmt.Errorf("unhandled state %s", p.State)
    }
}

